import{_ as t,o as a,c as l,a2 as n}from"./chunks/framework.z3u3TMv0.js";const p=JSON.parse('{"title":"30-Minuten-Quickstart","description":"Von null zur ersten lokalen Antwort in MiniTavern — Ollama oder LM Studio, Modell, LAN, App, ca. 30 Minuten.","frontmatter":{"title":"30-Minuten-Quickstart","description":"Von null zur ersten lokalen Antwort in MiniTavern — Ollama oder LM Studio, Modell, LAN, App, ca. 30 Minuten.","head":[["meta",{"name":"keywords","content":"Tavern,AI Tavern,MiniTavern,AI Begleiter,AI Freund,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobil,Silly Tavern Android,Silly Tavern iOS,AI Roleplay,Charakterkarte,AI Chat,mobiles AI,Offline-AI,AI Geschichte,lokales LLM,Ollama,LM Studio,Lorebook,Regex,BYOK,Handbuch,Anleitung"}],["meta",{"property":"og:title","content":"30-Minuten-Quickstart · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Von null zur ersten lokalen Antwort in MiniTavern — Ollama oder LM Studio, Modell, LAN, App, ca. 30 Minuten."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/de/quickstart"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/de/quickstart"}]]},"headers":[],"relativePath":"de/quickstart.md","filePath":"de/quickstart.md","lastUpdated":1787224147000}'),i={name:"de/quickstart.md"};function r(o,e,s,d,h,u){return a(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="_30-minuten-quickstart" tabindex="-1">30-Minuten-Quickstart <a class="header-anchor" href="#_30-minuten-quickstart" aria-label="Permalink to &quot;30-Minuten-Quickstart&quot;">​</a></h1><p>Ziel: von null bis zur ersten lokalen Modellantwort in MiniTavern.</p><table tabindex="0"><thead><tr><th>Schritt</th><th>ca. Zeit</th><th>Was</th></tr></thead><tbody><tr><td>1</td><td>0–5 min</td><td>Tool: Ollama oder LM Studio</td></tr><tr><td>2</td><td>5–15 min</td><td>installieren und kleines Modell laden</td></tr><tr><td>3</td><td>15–20 min</td><td>LAN / Local Server öffnen</td></tr><tr><td>4</td><td>20–25 min</td><td>LAN-IP des PCs finden</td></tr><tr><td>5</td><td>25–30 min</td><td>MiniTavern-Verbindung neu + Testen</td></tr></tbody></table><hr><h2 id="step-1-tool-wahlen" tabindex="-1">Step 1: Tool wählen <a class="header-anchor" href="#step-1-tool-wahlen" aria-label="Permalink to &quot;Step 1: Tool wählen&quot;">​</a></h2><ul><li><strong>Schnellstmöglich</strong>: <a href="/ultra_guides/de/ollama/install">Ollama</a> oder <a href="/ultra_guides/de/lmstudio/install">LM Studio</a></li><li><strong>Roleplay</strong>: später <a href="/ultra_guides/de/koboldcpp/install">KoboldCPP</a></li><li><strong>GGUF vorhanden</strong>: <a href="/ultra_guides/de/llamacpp/install">llama.cpp</a></li></ul><p>Vergleich: <a href="/ultra_guides/de/local/tools">Tool-Übersicht</a>. Unten <strong>Ollama</strong> als Beispiel; andere Tools «Modell laden / Dienst starten» analog, Step 5 gleich.</p><hr><h2 id="step-2-installieren-und-kleines-modell" tabindex="-1">Step 2: Installieren und kleines Modell <a class="header-anchor" href="#step-2-installieren-und-kleines-modell" aria-label="Permalink to &quot;Step 2: Installieren und kleines Modell&quot;">​</a></h2><ol><li>Nach <a href="/ultra_guides/de/ollama/install">Ollama installieren</a>.</li><li>Terminal (Beispiel, relativ klein, für den Pfadtest):</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span></code></pre></div><ol start="3"><li>Lokal prüfen:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span></code></pre></div><p>Nach Dialog <code>/bye</code> beenden. Mehr Auswahl: <a href="/ultra_guides/de/ollama/models">Modelle laden &amp; wählen</a>.</p><hr><h2 id="step-3-lan-zugriff" tabindex="-1">Step 3: LAN-Zugriff <a class="header-anchor" href="#step-3-lan-zugriff" aria-label="Permalink to &quot;Step 3: LAN-Zugriff&quot;">​</a></h2><p>Nach <a href="/ultra_guides/de/ollama/lan">LAN-Zugriff</a> <code>OLLAMA_HOST=0.0.0.0</code> und Firewall-Port <strong>11434</strong>.</p><p>Dann <strong>am PC</strong> im Browser (Antwort reicht, kein schönes UI nötig):</p><p><code>http://127.0.0.1:11434</code></p><hr><h2 id="step-4-lan-ip-des-pcs" tabindex="-1">Step 4: LAN-IP des PCs <a class="header-anchor" href="#step-4-lan-ip-des-pcs" aria-label="Permalink to &quot;Step 4: LAN-IP des PCs&quot;">​</a></h2><ul><li><strong>Windows</strong>: <code>Win + R</code> → <code>cmd</code> → <code>ipconfig</code>, unter WLAN-Adapter <strong>IPv4</strong> (<code>192.168.x.x</code>).</li><li><strong>macOS</strong>: Systemeinstellungen → Netzwerk → aktuelles Wi‑Fi → Details; oder <code>ipconfig getifaddr en0</code>.</li></ul><p>IP als <code>YOUR_PC_IP</code> notieren.</p><hr><h2 id="step-5-in-minitavern" tabindex="-1">Step 5: In MiniTavern <a class="header-anchor" href="#step-5-in-minitavern" aria-label="Permalink to &quot;Step 5: In MiniTavern&quot;">​</a></h2><ol><li>App → <strong>Einstellungen → Modelle → Modellverbindung → Neu</strong>.</li><li>Plattform <strong>Custom / OpenAI-kompatibel</strong> (App-Text gilt).</li><li>Ausfüllen:</li></ol><table tabindex="0"><thead><tr><th>Feld</th><th>Beispiel (Ollama)</th></tr></thead><tbody><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:11434/v1</code></td></tr><tr><td>API Key</td><td>leer oder beliebiger Platzhalter (lokal oft ungeprüft)</td></tr><tr><td>Modellname</td><td><code>llama3.2:3b</code> (wie <code>ollama list</code>)</td></tr></tbody></table><ol start="4"><li>Speichern und <strong>Testen</strong>; bei Erfolg Standard, Charakterkarte importieren und chatten.</li></ol><p>UI: <a href="/ultra_guides/de/connect-app/minitavern">In MiniTavern konfigurieren</a>.</p><hr><h2 id="fehlgeschlagen" tabindex="-1">Fehlgeschlagen? <a class="header-anchor" href="#fehlgeschlagen" aria-label="Permalink to &quot;Fehlgeschlagen?&quot;">​</a></h2><ul><li>Timeout, leere Antwort → <a href="/ultra_guides/de/troubleshoot">Fehlerbehebung</a></li><li>Häufigster Fehler: Base URL mit <strong><code>localhost</code></strong>, oder Handy und PC nicht im selben Wi‑Fi</li></ul>',32)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
